sections/about.liquid:
{%- if settings.about_body != blank or settings.about_image_url != blank -%}
  <section class="about-section">
    <div class="container about-section__inner">
      {%- if settings.about_image_url != blank -%}
        <img class="about-section__media" src="{{ settings.about_image_url }}" alt="" loading="lazy" width="1200" height="800">
      {%- endif -%}
      <div class="about-section__copy">
        {%- if settings.about_heading != blank -%}
          <h2>{{ settings.about_heading }}</h2>
        {%- endif -%}
        <p class="muted">{{ settings.about_body }}</p>
      </div>
    </div>
  </section>
{%- endif -%}

{% schema %}
{
  "name": "About",
  "settings": [],
  "presets": [{ "name": "About" }]
}
{% endschema %}

sections/announcement.liquid:
{%- if settings.announcement != blank -%}
  <div class="announcement-bar">
    <div class="container">{{ settings.announcement }}</div>
  </div>
{%- endif -%}

{% schema %}
{
  "name": "Announcement",
  "settings": [],
  "presets": [{ "name": "Announcement" }]
}
{% endschema %}

sections/custom-content.liquid:
{% comment %}
  Replaced at upload time with the store's own content blocks (EcomStrait
  builder). Empty here so the section renders nothing by default.
{% endcomment %}

{% schema %}
{
  "name": "Custom content",
  "settings": [],
  "presets": [{ "name": "Custom content" }]
}
{% endschema %}

snippets/price.liquid:
{%- liquid
  assign target = product
  if target == blank
    assign target = variant
  endif
-%}
{%- if target.compare_at_price > target.price -%}
  <span class="price price--sale">
    <s class="price__was">{{ target.compare_at_price | money }}</s>
    <span class="price__now">{{ target.price | money }}</span>
  </span>
{%- else -%}
  <span class="price">
    {%- if target.price_varies -%}From {% endif -%}{{ target.price | money }}
  </span>
{%- endif -%}
